export const MESSAGES = { pl, de, en };
export const LANGS = ['pl', 'de', 'en'];

export function resolveLang(l) {
  const s = String(l || '').toLowerCase().slice(0, 2);
  return s === 'pl' || s === 'de' ? s : 'en';
}

/** Language from the browser preferences: the first (primary) entry of the list decides. */
export function detectLang(list) {
  const first = Array.isArray(list) ? list[0] : list;
  return resolveLang(first);
}

export const has = (key) => Object.prototype.hasOwnProperty.call(en, key);

export function t(lang, key, params = {}) {
  const dict = MESSAGES[resolveLang(lang)];
  const tpl = dict[key] ?? en[key];
  if (tpl == null) return key;
  return tpl.replace(/\{(?:(\w+):)?(\w+)\}/g, (m, ns, name) => {
    const v = params?.[name];
    if (v == null) return '–';
    return ns ? t(lang, `${ns}.${v}`) : String(v);
  });
}

/** Price with a number of decimals that depends on its magnitude. */
export function fmtPrice(v) {
  if (v == null || !Number.isFinite(Number(v))) return '–';
  const a = Math.abs(v);
  return Number(v).toFixed(a >= 1000 ? 2 : a >= 20 ? 3 : a >= 1 ? 5 : 5);
}
